// Shape of public/data/campus.json, generated by scripts/build_campus.py.
// Coordinates are local metres: x = east, z = south (north is -z), y = up.

export type Pt = [number, number]

export interface Roof {
  /** OSM roof:shape — dome, cone, gabled, hipped, side_hipped, skillion, ... */
  s: string
  /** roof height in metres (part of the total height) */
  h?: number
  /** roof:direction, compass degrees the slope faces */
  d?: number
  /** roof:orientation — "across" puts the ridge on the short axis */
  o?: string
}

export interface Part {
  p: Pt[]
  /** holes */
  o?: Pt[][]
  /** top height in metres */
  h: number
  /** bottom height (min_height), e.g. bridges */
  b?: number
  r?: Roof
}

export type ModuleKey = 'interviews' | 'data' | 'thinking' | 'outcomes'

export interface CampusBuilding {
  key: string
  name: string
  /** A = landmark, B = other campus building on the official map */
  tier: 'A' | 'B'
  module?: ModuleKey
  /** shown in the hover card, e.g. for buildings drawn from the official map only */
  note?: string
  top: number
  anchor: Pt
  parts: Part[]
}

/** x, z, scale, type (0 = round crown, 1 = conifer) */
export type Tree = [number, number, number, number]

export interface Road {
  /** OSM highway class */
  k: string
  /** width in metres */
  w: number
  p: Pt[]
  n?: string
  /** one-way (drawn in the direction of travel) */
  o?: 1
}

/** A street joined into one polyline for ambient traffic; o = one-way, w = width in metres. */
export interface TrafficRoute {
  p: Pt[]
  o: 0 | 1
  w: number
}

export interface Campus {
  origin: [number, number]
  radius: number
  buildings: CampusBuilding[]
  context: Part[]
  roads: Road[]
  greens: { p: Pt[]; k: string }[]
  trees: Tree[]
  traffic: TrafficRoute[]
  /** footpaths near the hospital core, joined into polylines for pedestrians */
  walks: { p: Pt[] }[]
}

/** Loads the campus, reporting progress (0 … 1) as the file streams in. */
export async function loadCampus(onProgress?: (fraction: number) => void): Promise<Campus> {
  const res = await fetch(`${import.meta.env.BASE_URL}data/campus.json`)
  if (!res.ok) throw new Error(`Could not load campus data (HTTP ${res.status})`)
  if (!res.body || !onProgress) return res.json()
  // a compressed response reports its compressed length, so measure against the file size instead
  const total = res.headers.get('content-encoding') ? __CAMPUS_BYTES__ : Number(res.headers.get('content-length')) || __CAMPUS_BYTES__
  const reader = res.body.getReader()
  const chunks: Uint8Array[] = []
  let received = 0
  for (;;) {
    const { done, value } = await reader.read()
    if (done) break
    chunks.push(value)
    received += value.length
    onProgress(Math.min(1, received / total))
  }
  const bytes = new Uint8Array(received)
  let offset = 0
  for (const c of chunks) {
    bytes.set(c, offset)
    offset += c.length
  }
  return JSON.parse(new TextDecoder().decode(bytes)) as Campus
}
